type Constructor = new (...args: any[]) => {};

function Suspendable<TBase extends Constructor>(Base: TBase) {
    return class extends Base {                 // mixin: base in, subclass out
        suspended = false;
        toggle() { this.suspended = !this.suspended; }
    };
}

class BallItem extends Suspendable(GameItem) {  // one object, both behaviours
    click() { this.toggle(); }
}

