class BallThread extends ThreadBase {
    twin!: BallItem;                          // set by the factory, never by clients
    run() { while (!this.suspended) { this.twin.draw(); this.twin.step(); } }
}
class BallItem extends GameItem {
    twin!: BallThread;
    click() { this.twin.toggleSuspended(); }
}
function createBall(): BallItem {             // the definite-assignment ! is paid here
    const item = new BallItem(), driver = new BallThread();
    item.twin = driver; driver.twin = item;
    return item;
}
